import * as React from "react";

import { cn } from "../lib/utils";

import styles from "./share-bar.module.css";

export type ShareBarItem = {
  id: string;
  label: string;
  value: number;
  /** Any CSS colour. Defaults to the chart series in order, the same chart-1 to chart-6 the Chart uses. */
  color?: string;
};

export type ShareBarProps = Omit<React.ComponentProps<"div">, "children"> & {
  items: readonly ShareBarItem[];
  /** Names the bar for assistive technology, which hears it with every share, as in "Auth methods: Universal Auth 62%, ...". */
  label: string;
  /** What the shares are a part of. Defaults to the sum of the values; a larger total leaves the rest of the track empty. */
  total?: number;
  format?: (value: number) => string;
  legend?: boolean;
  /** Segments shown before the smallest items fold into one Other segment. Defaults to 6, the number of chart series, so no two segments share a colour. */
  max?: number;
  otherLabel?: string;
  empty?: React.ReactNode;
};

const series = [
  "var(--cipher-chart-1)",
  "var(--cipher-chart-2)",
  "var(--cipher-chart-3)",
  "var(--cipher-chart-4)",
  "var(--cipher-chart-5)",
  "var(--cipher-chart-6)"
];

const defaultFormat = (value: number) => value.toLocaleString();

const percent = (value: number, total: number) => {
  if (value <= 0 || total <= 0) return "0%";
  const share = (value / total) * 100;
  if (share < 1) return "<1%";
  if (share > 99 && value < total) return ">99%";
  return `${Math.round(share)}%`;
};

export function ShareBar({
  items,
  label,
  total,
  format = defaultFormat,
  legend = true,
  max = series.length,
  otherLabel = "Other",
  empty = "No data",
  className,
  ...props
}: ShareBarProps) {
  const id = React.useId();
  const [open, setOpen] = React.useState(false);
  const clean = items.map((item) => ({
    ...item,
    value: Number.isFinite(item.value) && item.value > 0 ? item.value : 0
  }));
  const sum = clean.reduce((acc, item) => acc + item.value, 0);
  const whole = typeof total === "number" && Number.isFinite(total) && total > sum ? total : sum;
  const limit = Math.max(2, Math.floor(max));
  const folded =
    clean.length > limit
      ? new Set(
          [...clean]
            .sort((a, b) => b.value - a.value)
            .slice(limit - 1)
            .map((item) => item.id)
        )
      : new Set<string>();
  const shown = clean.filter((item) => !folded.has(item.id));
  const rest = clean.filter((item) => folded.has(item.id));
  const rows = [
    ...shown.map((item, index) => ({
      ...item,
      color: item.color ?? series[index % series.length],
      other: false
    })),
    ...(rest.length
      ? [
          {
            id: "__other",
            label: `${otherLabel} (${rest.length})`,
            value: rest.reduce((acc, item) => acc + item.value, 0),
            color: undefined,
            other: true
          }
        ]
      : [])
  ];
  const summary =
    whole > 0
      ? `${label}: ${rows
          .filter((row) => row.value > 0)
          .map((row) => `${row.label} ${percent(row.value, whole)}`)
          .join(", ")}`
      : `${label}: ${typeof empty === "string" ? empty : "no data"}`;

  return (
    <div data-slot="share-bar" className={cn(styles.root, className)} {...props}>
      <div role="img" aria-label={summary} className={styles.bar}>
        {rows.map((row) =>
          row.value > 0 ? (
            <span
              key={row.id}
              className={styles.segment}
              data-other={row.other || undefined}
              style={{ flexGrow: row.value / whole, background: row.color }}
            />
          ) : null
        )}
        {whole > sum && sum > 0 && (
          <span className={styles.remainder} style={{ flexGrow: (whole - sum) / whole }} />
        )}
      </div>
      {legend &&
        (whole > 0 ? (
          <ul className={styles.legend}>
            {rows.map((row) => (
              <React.Fragment key={row.id}>
                <li className={styles.entry}>
                  <span
                    className={styles.swatch}
                    data-other={row.other || undefined}
                    style={{ background: row.color }}
                  />
                  {row.other ? (
                    <button
                      type="button"
                      className={cn(styles.name, styles.toggle)}
                      aria-expanded={open}
                      aria-controls={`${id}-folded`}
                      onClick={() => setOpen((value) => !value)}
                    >
                      {row.label}
                    </button>
                  ) : (
                    <span className={styles.name}>{row.label}</span>
                  )}
                  <span className={styles.share}>{percent(row.value, whole)}</span>
                  <span className={styles.count}>{format(row.value)}</span>
                </li>
                {row.other && (
                  <li id={`${id}-folded`} hidden={!open} className={styles.foldedGroup}>
                    <ul className={styles.folded}>
                      {rest.map((item) => (
                        <li key={item.id} className={styles.entry}>
                          <span />
                          <span className={styles.name}>{item.label}</span>
                          <span className={styles.share}>{percent(item.value, whole)}</span>
                          <span className={styles.count}>{format(item.value)}</span>
                        </li>
                      ))}
                    </ul>
                  </li>
                )}
              </React.Fragment>
            ))}
            <li className={cn(styles.entry, styles.total)}>
              <span />
              <span className={styles.name}>Total</span>
              <span />
              <span className={styles.count}>{format(whole)}</span>
            </li>
          </ul>
        ) : (
          <p className={styles.empty}>{empty}</p>
        ))}
    </div>
  );
}
ShareBar.displayName = "ShareBar";

.root {
  display: flex;
  width: 100%;
  min-width: 0;
  flex-direction: column;
  gap: var(--cipher-space-12);
}
.bar {
  display: flex;
  height: var(--cipher-space-10);
  gap: var(--cipher-space-2);
  overflow: hidden;
  background: var(--cipher-tint);
  box-shadow: inset 0 0 0 var(--cipher-size-control-border) var(--cipher-line-soft);
}
.segment {
  flex-basis: 0;
  flex-shrink: 1;
  min-width: var(--cipher-space-3);
}
.segment[data-other],
.swatch[data-other] {
  background: repeating-linear-gradient(
    135deg,
    var(--cipher-faint) 0 var(--cipher-space-2),
    transparent var(--cipher-space-2) var(--cipher-space-4)
  );
}
.remainder {
  flex-basis: 0;
  min-width: 0;
}
.legend {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto auto;
  column-gap: var(--cipher-space-12);
  row-gap: var(--cipher-space-8);
  margin: 0;
  padding: 0;
  list-style: none;
  font-family: var(--cipher-type-small-font-family);
  font-size: var(--cipher-type-small-font-size);
  line-height: var(--cipher-type-small-line-height);
}
.entry {
  display: grid;
  grid-column: 1 / -1;
  grid-template-columns: subgrid;
  align-items: start;
}
.swatch {
  width: var(--cipher-space-10);
  height: var(--cipher-space-10);
  margin-block-start: calc((var(--cipher-type-small-line-height) - var(--cipher-space-10)) / 2);
}
.name {
  min-width: 0;
  color: var(--cipher-ink);
  overflow-wrap: anywhere;
}
.toggle {
  justify-self: start;
  padding: 0;
  border: 0;
  background: none;
  font: inherit;
  text-align: start;
  text-decoration: underline dotted;
  text-underline-offset: var(--cipher-space-3);
  cursor: pointer;
}
.toggle:focus-visible {
  outline: var(--cipher-size-focus-ring) solid var(--cipher-ink);
  outline-offset: var(--cipher-size-focus-ring);
}
.foldedGroup {
  display: grid;
  grid-column: 1 / -1;
  grid-template-columns: subgrid;
}
.foldedGroup[hidden] {
  display: none;
}
.folded {
  display: grid;
  grid-column: 1 / -1;
  grid-template-columns: subgrid;
  row-gap: var(--cipher-space-8);
  margin: 0;
  padding: 0;
  list-style: none;
}
.folded .name,
.folded .count {
  color: var(--cipher-muted);
}
.share {
  color: var(--cipher-muted);
  font-variant-numeric: tabular-nums;
  text-align: end;
}
.count {
  min-width: 6ch;
  color: var(--cipher-ink);
  font-weight: var(--cipher-type-label-font-weight);
  font-variant-numeric: tabular-nums;
  text-align: end;
}
.total {
  padding-block-start: var(--cipher-space-8);
  border-top: var(--cipher-size-control-border) solid var(--cipher-line-soft);
}
.total .name {
  font-weight: var(--cipher-type-label-font-weight);
}
.empty {
  margin: 0;
  color: var(--cipher-muted);
  font-family: var(--cipher-type-small-font-family);
  font-size: var(--cipher-type-small-font-size);
  line-height: var(--cipher-type-small-line-height);
}
